-- Moments of each participant's run, for the analysis after an event: when
-- they opened the demo, when they reached the thanks screen, and whether they
-- downloaded the PDF there. Phones send these in the background and retry on
-- bad wifi, so an event can arrive minutes late, or twice.

create table if not exists public.participant_events (
	event_id text not null check (char_length(event_id) between 1 and 64),
	-- Generated by the phone and kept for the participant's whole run.
	participant_id uuid not null,
	kind text not null check (kind in ('opened', 'finished', 'pdf_download')),
	-- When it happened, by the phone's clock. Durations compare two times of
	-- the same phone, so they hold even when that clock is off.
	occurred_at timestamptz not null,
	-- When it reached the server; later than `occurred_at` after a retry.
	received_at timestamptz not null default now(),
	-- Each moment counts once per participant: a retry or a refresh keeps the first.
	primary key (event_id, participant_id, kind)
);

alter table public.participant_events enable row level security;

-- One row per participant: how long they took, and whether they took the PDF.
-- `duration` is null for participants who never reached the thanks screen.
create or replace view public.participant_durations
with (security_invoker = true) as
select
	event_id,
	participant_id,
	min(occurred_at) filter (where kind = 'opened') as opened_at,
	min(occurred_at) filter (where kind = 'finished') as finished_at,
	min(occurred_at) filter (where kind = 'finished')
		- min(occurred_at) filter (where kind = 'opened') as duration,
	bool_or(kind = 'pdf_download') as downloaded_pdf
from public.participant_events
group by event_id, participant_id;

revoke all on public.participant_events from anon, authenticated;
revoke all on public.participant_durations from anon, authenticated;
